(7098005, 1081988, 168306, '<td valign="top">Perfectly simple. Clean sheet of paper and a freshly sharpened pencil to signify a clean slate, a new beginning. Love it.</td>', 'Perfectly simple. Clean sheet of paper and a freshly sharpened pencil to signify a clean slate, a new beginning. Love it.', '2013-09-04 03:10:36.000000', NULL, 1),
